  (* [comment removed for export] *)
  Lemma vm_full : forall z, 0 <= z < 2 ^ 64 -> (zinP z (PM_LAZY sp0z X) -> zinP z (PM_S sp0z brk0z X)) -> VM (wa z) = FULL (wa z).
